def orfs(s, name):
    res=[]
    for f in range(3):
        i=f
        start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if start is None:
                if cod=="ATG":
                    start=i
            else:
                if cod in stops:
                    res.append((name, f, start, i+3, i+3-start))
                    start=None
            i+=3
    return res

