# tandem repeats: unit length 2..25, at least 3 copies (or 2 copies if unit>=15), approximate
def score_tandem(seq,p,i):
    # repeat starting at i with period p, count copies allowing 1 mismatch per unit
    unit=seq[i:i+p]
    j=i; reps=0
    while j+p<=n:
        mism=sum(1 for a,b in zip(seq[j:j+p],unit) if a!=b)
        if mism<=max(1,p//8):
            reps+=1; j+=p
        else:
            break
    return reps, j-i
