# longest stop-free stretch in each frame
def longest_stopfree(s,label):
    best=(0,None)
    for f in range(3):
        i=f; run=0; start=i
        while i+3<=len(s):
            if s[i:i+3] in stops:
                if run>best[0]: best=(run,(label,f,start+1,i))
                run=0; start=i+3
            else:
                run+=3
            i+=3
        if run>best[0]: best=(run,(label,f,start+1,i))
    return best
